    "exit_code": 0,
    "result": "2075 passed, 14472 assertions, 63.56 seconds; entire monorepo incl Sales, Shipping, Arch, Integration"
  },
  {
    "command": "python3 <Task package root>/scripts/plan.py check PLAN1 --json",
    "exit_code": 0,
    "result": "0 errors, 0 warnings"
  },
  {
